\label{prop:exact}
Let $A$ be row-stochastic and $0<\alpha<1$. Then
\begin{equation}
\kappa(\widetilde{A})=(1-\alpha)+\alpha\,\kappa(A)
\end{equation}
if and only if there exists a pair $(i,j)$ attaining
$\tfrac12\|A_{i\cdot}-A_{j\cdot}\|_1=\kappa(A)$ that satisfies
\begin{equation}\label{eq:cond}
A_{ii}\ \ge\ A_{ji}
\qquad\text{and}\qquad
A_{jj}\ \ge\ A_{ij}.
\end{equation}

\label{cor:floor}
Let $0<\alpha<1$. If the condition of Proposition~\ref{prop:exact} holds at
every layer, then $\kappa(\widetilde{A}^{(\ell)})=(1-\alpha)+\alpha\kappa(A^{(\ell)})$ for
all $\ell$. In particular, at $\alpha=\tfrac12$ the second inequality
in~\eqref{eq:their-product} is an equality:
\begin{equation*}
\prod_{\ell=1}^{L}\kappa\big(\widetilde{A}^{(\ell)}\big)\;=\;2^{-L}\prod_{\ell=1}^{L}\big(1+\kappa(A^{(\ell)})\big).
\end{equation*}
